local function separated(value: string?): string
  if value ~= nil then
    return value
  else
    if value ~= nil then
      return ""
    end
  end
  return ""
end

local function joined(value: string?, flag: boolean): string
  if flag then
    if value ~= nil then
      if value ~= nil then
        return value
      end
    end
  end
  if value ~= nil then
    return value
  end
  return ""
end

return 0
